import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"功耗分析 DPA","description":"","frontmatter":{"title":"功耗分析 DPA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/power-analysis-dpa.md","filePath":"cs/power-analysis-dpa.md","lastUpdated":1789023840000}'),c={name:"cs/power-analysis-dpa.md"};function A(E,a,_,f,u,B){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="功耗分析-dpa" tabindex="-1">功耗分析 DPA <a class="header-anchor" href="#功耗分析-dpa" aria-label="Permalink to &quot;功耗分析 DPA&quot;">​</a></h1><div class="epigraph"><p>运算的功耗与数据相关时，统计多条曲线就能抽出密钥比特。防护是掩码、随机化与恒定功耗设计，而不是把算法换成「更长的密钥」一句话。</p><footer>—— Kocher, Jaffe and Jun, Differential Power Analysis, CRYPTO 1999</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/firmware-security">固件</a>还在逻辑更新。缺口是<strong>物理可观测</strong>：功耗。主干侧信道已给时间；本课 DPA。不给采集与分析步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>智能卡、安全元件在敌手手上。简单功耗与差分功耗。缺口是实现对策：掩码、隐藏、随机延迟——代价是性能与随机数质量。</p><h3 id="实验室模型" tabindex="-1">实验室模型 <a class="header-anchor" href="#实验室模型" aria-label="Permalink to &quot;实验室模型&quot;">​</a></h3><p>课程只要求把功耗标进威胁模型。不指导搭建探针。</p><p><span class="marginnote">Kocher et al. 1999。禁止 DPA 实验指导。故障注入下一课是主动物理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述相关泄漏。对策分层。下一课故障注入。</p>',12)),(e(),n(h,null,{default:t(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E5%AF%86%E9%92%A5%E7%9B%B8%E5%85%B3%E8%BF%90%E7%AE%97%22%5D%20--%3E%20PWR%5B%22%E5%8A%9F%E8%80%97%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20PWR%20--%3E%20STAT%5B%22%E7%BB%9F%E8%AE%A1%E5%8C%BA%E5%88%86%E6%AF%94%E7%89%B9%22%5D%0A%20%20MASK%5B%22%E6%8E%A9%E7%A0%81%E4%B8%8E%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%20--%3E%20HARD%5B%22%E6%8F%90%E9%AB%98%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>物理 C 泄漏。故障下一课主动改计算。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写探针实验。故障注入下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固件逻辑之后，功耗把数据变成曲线。</li><li>DPA 是统计侧信道；对策是掩码与隐藏。</li><li>密钥加长不自动关功耗泄漏。</li><li>下一课故障注入。</li><li>出处：Kocher, Jaffe and Jun, 1999。</li></ul>',8))])}const D=i(c,[["render",A]]);export{P as __pageData,D as default};
